const socks = [...Array(6).fill('red'), ...Array(4).fill('blue'), ...Array(2).fill('green')];
const n = socks.length;
const fewestBlue = Array(n + 1).fill(Infinity);
for (let mask = 0; mask < 1 << n; mask++) {
  let size = 0;
  let blue = 0;
  for (let i = 0; i < n; i++) {
    if (mask & (1 << i)) {
      size++;
      if (socks[i] === 'blue') blue++;
    }
  }
  fewestBlue[size] = Math.min(fewestBlue[size], blue);
}
for (let k = 1; k <= n; k++) if (fewestBlue[k] >= 2) return k;
return NaN;
